    function recognitionModelStatusText(status) { return status === "queued" ? "等待开始" : status === "running" ? "正在调用" : status === "response_saved" ? "回答已收到" : status === "analysis_failed" ? "本地整理失败" : status === "completed" ? "已完成" : status === "unknown" ? "模型无法确认" : status === "unsupported" ? "模型不支持" : "Provider 调用失败"; }
